import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../main.dart';
class SettingsScreen extends StatelessWidget { const SettingsScreen({super.key}); @override Widget build(BuildContext context) { final state = context.watch<AppState>(); return ListView(padding: const EdgeInsets.all(32), children: [Text('SYSTEM / CONFIGURATION', style: Theme.of(context).textTheme.labelSmall?.copyWith(color: const Color(0xFF00D97E), letterSpacing: 1.5)), const SizedBox(height: 8), Text('Settings', style: Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight: FontWeight.w800)), const SizedBox(height: 28), Card(child: Column(children: [ListTile(title: const Text('Server URL'), subtitle: Text(state.server.serverUrl ?? 'Not configured'), trailing: IconButton(icon: const Icon(Icons.edit_outlined), onPressed: () => _editUrl(context, state))), const Divider(height: 1), ListTile(title: const Text('Default printer'), trailing: DropdownButton<String?>(value: state.defaultPrinterId, hint: const Text('None'), items: [const DropdownMenuItem<String?>(value: null, child: Text('None')), ...state.printers.map((printer) => DropdownMenuItem<String?>(value: printer.id, child: Text(printer.name)))], onChanged: state.setDefaultPrinter)), const Divider(height: 1), ListTile(title: const Text('Polling interval'), subtitle: Text('${state.pollingInterval.inSeconds} seconds'), trailing: SizedBox(width: 160, child: Slider(value: state.pollingInterval.inSeconds.toDouble(), min: 10, max: 300, divisions: 29, label: '${state.pollingInterval.inSeconds}s', onChanged: (value) => state.setPollingInterval(Duration(seconds: value.round()))))), const Divider(height: 1), SwitchListTile(title: const Text('Dark mode'), value: state.darkMode, onChanged: state.setDarkMode), SwitchListTile(title: const Text('Launch at startup'), value: state.autoStart, onChanged: state.setAutoStart)])), const SizedBox(height: 18), Card(child: Column(children: [ListTile(title: const Text('Connection test'), subtitle: Text(state.connected ? 'WebSocket is receiving heartbeats.' : 'No active device connection.'), trailing: FilledButton(onPressed: state.testConnection, child: const Text('Test'))), const Divider(height: 1), ListTile(title: const Text('Reset device registration'), subtitle: const Text('Clear credentials and run setup again.'), trailing: TextButton(onPressed: state.reset, child: const Text('Reset')))]))]); }
  Future<void> _editUrl(BuildContext context, AppState state) async { final controller = TextEditingController(text: state.server.serverUrl); final value = await showDialog<String>(context: context, builder: (_) => AlertDialog(title: const Text('Server URL'), content: TextField(controller: controller), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: () => Navigator.pop(context, controller.text), child: const Text('Save'))])); if (value != null) state.updateServerUrl(value); }
}
